/**
 * Core shapes and one-line wording (server `workflow/orchestrator/mod.rs`, plan
 * `docs/plan/261022-agent-composer.md` §6–§7). Agent's tabs, floating terminal and the end
 * question read these; the draft copies this file.
 */

export type CoreChild = {
	project: string;
	label: string;
	task: string;
	text: string;
	/** `queued` · `running` · `paused` · `done` · `gone` (merged or discarded). */
	status: string;
	kind: string;
	cost: number;
	rounds: number;
	after: string | null;
	mergeReady: boolean;
	log: string;
	/** The person took it in its project: the core no longer decides for it. */
	touched: boolean;
};

export type Core = {
	id: string;
	title: string;
	text: string;
	at: number;
	status: "running" | "ended";
	routine: string | null;
	children: CoreChild[];
	/** The core's own log terminal (`core-oN`). */
	log: string;
	/** Its Lead pty once a message started it. */
	lead: string | null;
	lastInput: number;
	endedAt: number | null;
};

export type Choice = { key: string; label: string; detail: string; irreversible: boolean };
export type Question = { key: string; text: string; choices: Choice[]; default: string; tasks: string[] };
export type Impact = { id: string; title: string; children: CoreChild[]; questions: Question[]; notes: string[] };

export function childLive(child: CoreChild) {
	return child.status === "queued" || child.status === "running";
}

/** `●` while a child or the Lead works, `○` while it waits (a paused child, a queue behind it). */
export function coreBusy(core: Core) {
	return core.status === "running" && (core.children.some((child) => child.status === "running") || core.lead != null);
}

/** The chip under the terminal title: what the child is doing now. */
export function childState(child: CoreChild) {
	if (child.status === "gone") return "landed";
	if (child.mergeReady) return "to merge";
	if (child.status === "running") return child.kind === "running" ? "working" : child.kind;
	return child.status;
}

/** The answers a person starts from: each question's default. */
export function defaultAnswers(impact: Impact): Record<string, string> {
	return Object.fromEntries(impact.questions.map((question) => [question.key, question.default]));
}

/** The irreversible choices picked, so the dialog confirms them once more. */
export function irreversiblePicked(impact: Impact, answers: Record<string, string>) {
	return impact.questions.flatMap((question) =>
		question.choices
			.filter((choice) => choice.irreversible && answers[question.key] === choice.key)
			.map((choice) => ({ question, choice })),
	);
}

